import * as fs from 'fs';
import * as path from 'path';

interface RawEvent {
  event_id: string;
  event_ts: string;
  user_id: string;
  event_type: string;
  value: string;
}

interface Event {
  event_id: string;
  event_ts: string; // ISO format for JSON
  user_id: string;
  event_type: string;
  value: number;
}

// Convert DD/MM/YYYY format to ISO 8601
function normalizeDate(dateStr: string): string {
  // If already in ISO format, return as is
  if (dateStr.includes('T') || dateStr.includes('Z')) {
    return dateStr;
  }

  // Handle DD/MM/YYYY format
  if (dateStr.includes('/')) {
    const [day, month, year] = dateStr.split('/');
    return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}T00:00:00Z`;
  }

  return dateStr;
}

// Convert various null representations to 0
function normalizeValue(valueStr: string): number {
  if (!valueStr || valueStr.trim() === '' || valueStr.toLowerCase() === 'null' || valueStr.toLowerCase() === 'n/a') {
    return 0;
  }
  const parsed = parseFloat(valueStr);
  return isNaN(parsed) ? 0 : parsed;
}

async function loadCsvFiles(): Promise<Event[]> {
  const csvDir = '/data/csv';
  const files = fs.readdirSync(csvDir).filter(f => f.endsWith('.csv')).sort();

  console.log(`Found ${files.length} CSV files: ${files.join(', ')}`);

  let allEvents: Event[] = [];

  for (const file of files) {
    const filePath = path.join(csvDir, file);
    const content = fs.readFileSync(filePath, 'utf8');

    console.log(`\nProcessing ${file}:`);

    // Split into lines and remove empty lines
    let lines = content.split('\n').map(line => line.trim()).filter(line => line);

    // Remove trailing commas from all lines
    lines = lines.map(line => line.replace(/,$/, ''));

    console.log(`  Raw lines: ${lines.length}`);

    // Remove duplicate headers (keep only first header)
    const headerLine = lines[0];
    const dataLines = lines.slice(1).filter(line => line !== headerLine);

    console.log(`  After removing duplicate headers: ${dataLines.length} data lines`);

    // Parse each data line
    for (const line of dataLines) {
      const columns = line.split(',');
      if (columns.length >= 5) {
        const event: Event = {
          event_id: columns[0].trim(),
          event_ts: normalizeDate(columns[1].trim()),
          user_id: columns[2].trim(),
          event_type: columns[3].trim(),
          value: normalizeValue(columns[4].trim())
        };
        allEvents.push(event);
        console.log(`    Processed: ${event.event_id} | ${event.event_ts} | ${event.value}`);
      }
    }
  }

  console.log(`\nTotal events processed: ${allEvents.length}`);
  return allEvents;
}

async function ingestEvents(events: Event[]): Promise<void> {
  const ingestUrl = 'http://localhost:4000/ingest/Event';

  console.log(`\nIngesting ${events.length} events to ${ingestUrl}...`);

  for (let i = 0; i < events.length; i++) {
    const event = events[i];
    try {
      const response = await fetch(ingestUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(event),
      });

      if (!response.ok) {
        const errorText = await response.text();
        console.error(`Failed to ingest event ${event.event_id}: ${response.status} - ${errorText}`);
      } else {
        console.log(`✓ Ingested event ${i + 1}/${events.length}: ${event.event_id}`);
      }
    } catch (error) {
      console.error(`Error ingesting event ${event.event_id}:`, error);
    }
  }
}

async function main() {
  try {
    console.log('=== CSV Data Cleaning and Loading ===');

    // Load and clean CSV data
    const events = await loadCsvFiles();

    if (events.length === 0) {
      console.log('No events found to ingest.');
      return;
    }

    // Wait a moment to ensure Moose is ready
    console.log('\nWaiting 3 seconds for Moose to be ready...');
    await new Promise(resolve => setTimeout(resolve, 3000));

    // Ingest events
    await ingestEvents(events);

    console.log('\n=== Data loading complete! ===');
  } catch (error) {
    console.error('Error during data loading:', error);
    process.exit(1);
  }
}

main();

